-- 1. "Not applicable" charging speed is NULL, not 0 (0 was a workaround that forced the
--    CHECK constraint open). Restore the original 1..10 range; NULL passes CHECK.
ALTER TABLE car_models DROP CONSTRAINT IF EXISTS car_models_score_charging_check;
UPDATE car_models SET score_charging = NULL WHERE score_charging = 0;
ALTER TABLE car_models ADD CONSTRAINT car_models_score_charging_check
  CHECK (score_charging BETWEEN 1 AND 10);

-- 2. Slugs generated by stripping non-ASCII lost letters: 'Škoda' -> 'koda-…', 'Citroën' -> 'citro-n-…'.
UPDATE car_models SET slug = 'skoda-' || substr(slug, 6)   WHERE slug LIKE 'koda-%';
UPDATE car_models SET slug = replace(slug, 'citro-n', 'citroen') WHERE slug LIKE 'citro-n%';

-- 3. Tesla Model 3 Performance pointed at its own wikipedia_query, splitting it from its family.
UPDATE car_models SET wikipedia_query = 'Tesla Model 3' WHERE slug = 'tesla-model3-performance';
